const number = (n:number|null, digits=1) => n===null?'—':Number.isFinite(n)?moneyFormat(n,digits):'∞';
const dollars = (n:number, signed=false) => (signed&&n>0?'+':n<0?'−':'')+'$'+moneyFormat(Math.abs(n));
const tone = (n:number) => n>0?'positive':n<0?'negative':'';
const tabs = [{id:'overview',label:'首页',icon:LayoutDashboard},{id:'records',label:'记录',icon:ClipboardList},{id:'review',label:'分析',icon:BarChart3},{id:'rules',label:'设置',icon:ShieldCheck}];
const recordTabs=[['records','每日观察'],['trades','独立交易'],['positions','当前持仓'],['opportunities','Setup机会日志'],['history','历史记录']];
const analysisTabs=[['review','验证总览'],['g1','G1双向策略'],['models','四模型统计'],['psychology','纪律与心理'],['sunday','周报与月报'],['growth','个人成长'],['advanced','高级交易研究']];
const settingTabs=[['multi','多品种配置'],['account','账户和风险'],['fees','交易费用'],['contract','合约规格'],['g1','G1规则'],['discipline','纪律参数'],['period','验证周期'],['advanced','高级参数'],['data','数据管理']];
const sectionFor=(page:string)=>recordTabs.some(([k])=>k===page)?'records':analysisTabs.some(([k])=>k===page)?'review':page==='rules'?'rules':'overview';
