const modelDescriptions = [
  {id:'S1',name:'供应区反弹失败',direction:'做空',desc:'4小时下降趋势；供应区出现双顶、头肩顶、上影拒绝或更低高点。1小时信号入场。'},
  {id:'S2',name:'跌破后的反抽失败',direction:'做空',desc:'重要支撑跌破，反抽无法收复，形成 h 形结构；顺下降趋势执行。'},
  {id:'L1',name:'需求区二次下探',direction:'做多',desc:'上涨趋势中，需求区出现双底、二次下探失败或更高低点。1小时确认。'},
  {id:'L2',name:'回调结束与突破回踩',direction:'做多',desc:'上涨趋势中的牛旗、ABC 回调结束，或突破后回踩关键位不破。'},
];

async function api<T = {ok:boolean}>(url:string, method='GET', body?:unknown) {
  const response = await fetch(url, { method, credentials:'same-origin', headers:body?{'Content-Type':'application/json'}:undefined, body:body?JSON.stringify(body):undefined, cache:'no-store' });
  const data=await response.json() as T & {error?:string}; if(!response.ok)throw new Error(data.error||'操作失败，请重试。'); return data;
}
function exportCSV(records:DailyRecord[],settings:Settings,isDemo:boolean) {
  download(dailyCSV(records,settings,isDemo),'text/csv;charset=utf-8',`黄金验证_${isDemo?'示例':'正式'}_${todayCN()}.csv`);
}
function download(content:string,type:string,name:string){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

export default function Dashboard() {
  const [instrument,setInstrument]=useState<'all'|Instrument>('all'),accountId='all';
  const [page,setPage]=useState('overview'),[settingsTab,setSettingsTab]=useState('account'),[quickMenu,setQuickMenu]=useState(false),[tradeAction,setTradeAction]=useState<string|undefined>();
  const navigate=(next:string)=>{setPage(next);setQuickMenu(false);if(next!=='overview'&&next!=='records'&&next!=='review')setDemo(false);if(typeof window!=='undefined')window.history.replaceState(null,'','#'+next);};
  useEffect(()=>{const restore=()=>{const raw=window.location.hash.slice(1),next=aliases[raw]??raw;if(raw.startsWith('contract-settings')){setPage('rules');setSettingsTab('multi');return;}if([...tabs.map(t=>t.id),...recordTabs.map(t=>t[0]),...analysisTabs.map(t=>t[0])].includes(next))setPage(next);};restore();window.addEventListener('hashchange',restore);return()=>window.removeEventListener('hashchange',restore);},[]);
  const [trades,setTrades]=useState<TradeRecord[]>([]),[images,setImages]=useState<TradeImage[]>([]),[tradeEditor,setTradeEditor]=useState<TradeRecord|null>(null),[historyDate,setHistoryDate]=useState(todayCN);
  const scopedTrades=useMemo(()=>trades.filter(t=>instrument==='all'||instrumentOf(t)===instrument),[trades,instrument]);
  const legacyTrades=useMemo(()=>trades.filter(t=>instrumentOf(t)==='XAU'),[trades]);

  const [opportunities,setOpportunities]=useState<Opportunity[]>([]),[pendingOpportunity,setPendingOpportunity]=useState<{opportunity:Opportunity;tradeId:string}|null>(null);
  const [drafts,setDrafts]=useState<DailyDraft[]>([]);
  const [demo,setDemo]=useState(false), [demoRecords,setDemoRecords]=useState<DailyRecord[]>(generateDemo), [records,setRecords]=useState<DailyRecord[]>([]);
  const [settings,setSettings]=useState<Settings>(DEFAULT_SETTINGS), [demoSettings,setDemoSettings]=useState<Settings>(DEFAULT_SETTINGS);
  const unified=!!unifiedAccountConfig(settings),legacyView=instrument==='XAU'&&!unified;
  const accountTrades=useMemo(()=>unified?trades.map(t=>({...t,accountId:accountOf(t,settings),contract:tradeContract(t,settings)})):legacyTrades,[trades,legacyTrades,settings,unified]);
  const [loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState('');
  const [granularity,setGranularity]=useState<Granularity>('week');
  const [filters,setFilters]=useState<Filters>({start:DEFAULT_SETTINGS.start,end:DEFAULT_SETTINGS.end,compliance:'all',model:'all'});
  const [editor,setEditor]=useState<DailyRecord|null>(null), [saving,setSaving]=useState(false), [showInfo,setShowInfo]=useState(false),[deleting,setDeleting]=useState<string|null>(null);
  const [query,setQuery]=useState('');
  const activeSettings=demo?demoSettings:settings, rawRecords=demo?demoRecords:records;
  const financialRecords=useMemo(()=>ledgerDays(records,accountTrades,settings.accountCurrency as string??'USD'),[records,accountTrades,settings.accountCurrency]);
  const activeRecords=demo?demoRecords:financialRecords;
  const openDay=(date:string)=>{setHistoryDate(date);setEditor(structuredClone(rawRecords.find(d=>d.date===date)??{...blankDay(date),disciplineAssessed:false,fomoRecorded:false,quick:blankQuick()}));};
  const newTrade=(date=todayCN())=>{setDemo(false);setTradeAction(undefined);navigate('trades');setTradeEditor({...blankTrade(date),instrument:undefined,accountId:'legacy',contract:structuredClone(settings.g1?.contract??DEFAULT_G1.contract),recordType:'executed'});};
  const actOnTrade=(t:TradeRecord,a:string)=>{setTradeAction(a);setTradeEditor(t);};
  async function load(){setLoading(true);setError('');try{const d=await api<{records:DailyRecord[];settings:Settings|null;drafts:DailyDraft[];trades:TradeRecord[];images:TradeImage[];opportunities:Opportunity[]}>('/api/records');setOpportunities(d.opportunities??[]);setRecords(d.records);setTrades(d.trades??[]);setImages(d.images??[]);setDrafts(d.drafts??[]);setSettings(d.settings??DEFAULT_SETTINGS);}catch(e){setError((e as Error).message);}finally{setLoading(false);}}
  useEffect(()=>{void load();},[]);
  useEffect(()=>{setFilters({start:activeSettings.start,end:activeSettings.end,compliance:'all',model:'all'});setQuery('');},[demo,activeSettings.start,activeSettings.end]);
  useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(timer);},[toast]);
  const fullPoints=useMemo(()=>equitySeries(activeRecords,activeSettings),[activeRecords,activeSettings]);
  const filtered=useMemo(()=>filterRecords(fullPoints,filters),[fullPoints,filters]);
  const stats=useMemo(()=>summarize(filtered,activeSettings,filtered),[filtered,activeSettings]);
  const periods=useMemo(()=>aggregate(filtered,activeSettings,granularity),[filtered,activeSettings,granularity]);
  const assessment=evaluation(filtered,activeSettings);
  const completed=demo?dayDistance(activeSettings.start,activeSettings.end)+1:Math.max(0,Math.min(dayDistance(activeSettings.start,todayCN())+1,dayDistance(activeSettings.start,activeSettings.end)+1));
  const totalDays=dayDistance(activeSettings.start,activeSettings.end)+1;
  const priorRecords=activeRecords.filter(d=>d.date<activeSettings.start||d.date>activeSettings.end);
  const isFiltered=filters.start!==activeSettings.start||filters.end!==activeSettings.end||filters.compliance!=='all'||filters.model!=='all';
  const list=filtered.filter(d=>!query||[d.date,d.note,d.environment,d.pattern,...d.trades.map(t=>t.model)].join(' ').toLowerCase().includes(query.toLowerCase())).slice().reverse();
  const makeNew=()=>openDay(todayCN());
  async function saveDay(record:DailyRecord){
    setSaving(true);
    try { if(!demo){const data=await api<{record:DailyRecord}>('/api/records','PUT',record);record=data.record;}
      const update=(old:DailyRecord[])=>[...old.filter(d=>d.date!==record.date),record].sort((a,b)=>a.date.localeCompare(b.date));
      (demo?setDemoRecords:setRecords)(update);if(!demo)setDrafts(old=>old.filter(d=>d.record.date!==record.date));setEditor(null);setToast(demo?'示例记录已更新，未写入正式验证。':'每日记录已保存。');
    } finally {setSaving(false);}
  }
  async function removeDay(date:string){setSaving(true);try{if(!demo)await api('/api/records?date='+date,'DELETE');(demo?setDemoRecords:setRecords)(old=>old.filter(d=>d.date!==date));setDeleting(null);setToast('记录已删除。');}catch(e){setToast((e as Error).message);}finally{setSaving(false);}}
  async function saveConfig(value:Settings){if(demo){setDemoSettings(value);setToast('示例设置已更新。');}else{const result=await api<{settings:Settings}>('/api/settings','PUT',value);setSettings(result.settings);setToast('验证设置已保存。');}}
  async function exportAll(){
    try {
      const data=demo?{records:demoRecords,settings:demoSettings,drafts:[]}:await api<{records:DailyRecord[];settings:Settings|null;drafts:DailyDraft[]}>('/api/records?export=1');
      download(JSON.stringify({version:4,dataset:demo?'demo':'live',exportedAt:new Date().toISOString(),...data,statisticsBasis:'已实现平仓净损益按平仓日；整笔R及胜率只在全部平仓后计算；每日状态单独按日计数',imageFiles:'截图原图通过每笔详情的下载按钮导出，元数据保持关联'},null,2),'application/json',`黄金验证_${demo?'示例':'正式'}_完整数据_${todayCN()}.json`);
    }catch(e){setToast((e as Error).message);}
  }
  return <div className="app-shell">
    <aside className="sidebar">
      <a className="brand" href="#" onClick={e=>{e.preventDefault();setPage('overview');}} aria-label="回到总览"><div className="brand-mark"><TrendingUp size={22}/></div><div><strong>多品种策略实验室</strong><span>GOLD · STRATEGY LAB</span></div></a>
      <div className="workspace-label">个人策略工作台</div>
      <nav aria-label="主导航">{tabs.map(t=><button className={'nav-item '+(sectionFor(page)===t.id?'active':'')} key={t.id} onClick={()=>navigate(t.id)}><t.icon size={19}/>{t.label}{sectionFor(page)===t.id&&<span className="nav-dot"/>}</button>)}</nav>
      <div className="sidebar-note"><span className="eyebrow">验证的目标</span><p>少一点主观判断，<br/>多一点可验证的证据。</p><div className="small-rule"/><span>不设月度盈利任务<br/>验证长期正期望与稳定执行</span></div>
      <div className="sidebar-bottom"><div className="private-label"><LockKeyhole size={14}/>本机独立存储</div><div className="profile"><div className="avatar">T</div><div><strong>交易员</strong><span>三个月 · 一套系统</span></div><ShieldCheck size={17}/></div></div>
    </aside>
    <div className="main-shell">
      <header className="topbar"><div className="breadcrumb">黄金策略验证 <ChevronRight size={14}/><span>{tabs.find(t=>t.id===sectionFor(page))?.label}</span></div><div className="topbar-right"><span className="sync"><i className={error?'error-dot':''}/>{loading?'读取记录中':error?'连接待重试':demo?'示例模式':'正式记录已连接'}</span><span className="private-pill"><LockKeyhole size={12}/>私人网站</span></div></header>
      <main><div className="asset-scope"><div className="segmented" role="tablist" aria-label="交易品种范围">{(['all',...INSTRUMENTS] as const).map(id=><button role="tab" aria-selected={instrument===id} className={instrument===id?'selected':''} key={id} onClick={()=>{setInstrument(id);setDemo(false);}}>{id==='all'?'全部品种':INSTRUMENT_LABELS[id]}</button>)}</div><span className="badge subtle">统一账户 · USD</span></div>
        <div className="page-heading"><div><div className="eyebrow">THREE MONTHS. ONE SYSTEM.</div><h1>{page==='overview'?'策略验证总览':page==='records'?'把每一天记录清楚':page==='review'?'用样本评估，而非感觉':page==='growth'?'照顾状态，让执行更稳定':page==='g1'?'G1，用执行样本验证优势':page==='trades'?'每一笔交易，独立记录':page==='sunday'?'周报与月报':page==='positions'?'管理当前持仓':page==='history'?'补全过去，保留证据':page==='models'?'四种入场模型，独立比较':page==='opportunities'?'看见机会，也记录放弃':page==='psychology'?'情绪与执行，分别观察':page==='advanced'?'按需要展开深入研究':'规则与风险设置'}</h1><p>{page==='overview'?'看清收益，也看清你是如何得到它的。':page==='records'?'盈利、亏损和空仓日，都属于验证的一部分。':page==='review'?'将策略表现与执行偏差分开，找到值得保留的部分。':page==='growth'?'观察情绪、精力与交易的共同变化，慢慢找到自己的节奏。':page==='g1'?'记录机会、分仓与止损，追踪每个完整交易假设。':page==='trades'?'保存自己的计划、执行与结构证据，不重复填写每日状态。':page==='sunday'?'核对交易、执行和精力变化，再选下一周的一项改进。':'日线 / 4小时定环境，1小时找入场，15分钟仅辅助。'}</p></div><button className="button primary" disabled={!demo&&(loading||!!error)} onClick={()=>setQuickMenu(v=>!v)}><Plus size={17}/>记录</button></div>
        {quickMenu&&<div className="quick-record-menu"><button onClick={()=>{setQuickMenu(false);makeNew();}}>今日快速打卡</button><button onClick={()=>{setQuickMenu(false);newTrade();}}>新建交易</button><button onClick={()=>navigate('positions')}>管理持仓</button><button onClick={()=>navigate('opportunities')}>记录交易机会</button></div>}
        {sectionFor(page)!=='overview'&&<div className="workspace-tabs" role="tablist" aria-label={sectionFor(page)==='records'?'记录分类':sectionFor(page)==='review'?'分析分类':'设置分类'}>{(sectionFor(page)==='records'?recordTabs:sectionFor(page)==='review'?analysisTabs:settingTabs).map(([key,label])=><button role="tab" aria-selected={sectionFor(page)==='rules'?settingsTab===key:page===key} className={(sectionFor(page)==='rules'?settingsTab===key:page===key)?'selected':''} key={key} onClick={()=>sectionFor(page)==='rules'?setSettingsTab(key):navigate(key)}>{label}</button>)}</div>}
        {!demo&&trades.some(t=>!t.archived&&assetTradeCurrency(t,settings)!==(settings.accountCurrency??'USD'))&&<p className="warning-note">账户统计按 {String(settings.accountCurrency??'USD')} 计算。其他币种交易仍保留在交易列表，未自动换汇或混加金额；请按真实结算单位核对分类。</p>}
        {error&&<div role="alert" className="error-banner">{error}<button onClick={()=>void load()}>重试连接</button></div>}
        <details className={'mode-banner '+(demo?'demo':'live')} open={demo}><summary>{demo?'示例模式 · 与正式数据隔离':'数据范围与统计口径'}</summary><div className="mode-copy">{demo?<FlaskConical size={19}/>:<ShieldCheck size={19}/>}<div><strong>{demo?'正在查看示例数据':'正式验证记录'}</strong><span>{demo?'虚构的完整周期样本，用于试填与筛选；修改仅保留本次页面会话。':'记录随账号保存。只计验证期内已平仓、扣费后的净损益。'}</span></div></div><div className="segmented mode-switch"><button aria-pressed={demo} className={demo?'selected':''} disabled={!['overview','records','review','models'].includes(page)} onClick={()=>setDemo(true)}>示例数据</button><button aria-pressed={!demo} disabled={loading||!!error} className={!demo?'selected':''} onClick={()=>setDemo(false)}>正式记录</button></div></details>
        {!demo&&drafts.length>0&&<div className="draft-recovery"><strong>未提交草稿</strong><span>可继续填写，确认提交后才计入统计。</span>{drafts.map(d=><button key={d.record.date} onClick={()=>setEditor(structuredClone(d.record))}>{d.record.date} · 继续填写<ChevronRight size={13}/></button>)}</div>}
        {['overview','records','history','review','models','advanced','sunday','psychology'].includes(page)&&<>
        <section className="period-strip"><div className="period-title"><CalendarDays size={18}/><div><strong>{activeSettings.start.replaceAll('-','.')} — {activeSettings.end.replaceAll('-','.')}</strong><span>{demo?'模拟整个验证周期':`正式验证第 ${completed} / ${totalDays} 天`} · 已记录 {fullPoints.filter(d=>d.hasDailyState!==false).length} 天</span></div></div><div className="progress-block"><div className="progress-meta"><span>验证期进度</span><strong>{Math.round(completed/totalDays*100)}%</strong></div><div className="progress-track"><div style={{width:completed/totalDays*100+'%'}}/></div></div><button className="icon-text" onClick={()=>setShowInfo(true)}><CircleHelp size={16}/>统计口径</button></section>
        {(demo||legacyView)?<div className="filter-bar"><div className="segmented">{[['day','日'],['week','周'],['month','月']].map(([k,label])=><button key={k} aria-pressed={granularity===k} className={granularity===k?'selected':''} onClick={()=>setGranularity(k as Granularity)}>按{label}</button>)}</div><label className="date-filter"><span>从</span><input aria-label="筛选开始日期" type="date" value={filters.start} onChange={e=>setFilters({...filters,start:e.target.value})}/></label><label className="date-filter"><span>至</span><input aria-label="筛选结束日期" type="date" value={filters.end} onChange={e=>setFilters({...filters,end:e.target.value})}/></label><select aria-label="计划遵守筛选" value={filters.compliance} onChange={e=>setFilters({...filters,compliance:e.target.value as Filters['compliance']})}><option value="all">全部执行情况</option><option value="yes">遵守计划的日子</option><option value="no">未守计划的日子</option></select><select aria-label="交易模型筛选" value={filters.model} onChange={e=>setFilters({...filters,model:e.target.value})}><option value="all">全部模型</option>{MODELS.map(m=><option key={m}>{m}</option>)}</select>{isFiltered&&<button className="icon-button" aria-label="重置筛选" onClick={()=>setFilters({start:activeSettings.start,end:activeSettings.end,compliance:'all',model:'all'})}><RotateCcw size={16}/></button>}<button className="icon-text export-button" onClick={()=>exportCSV(filtered,activeSettings,demo)}><Download size={15}/>导出</button></div>:<div className="filter-bar"><label className="date-filter"><span>从</span><input aria-label="多品种开始日期" type="date" value={filters.start} onChange={e=>setFilters({...filters,start:e.target.value})}/></label><label className="date-filter"><span>至</span><input aria-label="多品种结束日期" type="date" value={filters.end} onChange={e=>setFilters({...filters,end:e.target.value})}/></label></div>}
        {filters.start>filters.end&&<div className="error-banner">筛选开始日期晚于结束日期，请调整区间。</div>}
        {filters.model!=='all'&&<p className="filter-note">模型筛选显示“包含 {filters.model} 的日子”，日收益包含这些日子的全部平仓单；单模型净收益请看周期评估。</p>}
        {priorRecords.length>0&&<p className="filter-note">有 {priorRecords.length} 天位于验证期外，已排除本期统计。可在每日记录页查看。</p>}
        </>}
        {page==='overview'&&!demo&&!legacyView&&<section className="card today-brief"><div><span className="eyebrow">{todayCN()} · 北京时间</span><h2>先记录状态，再执行计划</h2><p>每日观察与个人状态按账号统一保存，三个品种共用同一账户，按品种查看表现。</p></div><div className="today-actions"><button className="button primary" onClick={()=>openDay(todayCN())}>今日快速打卡</button><button className="button secondary" onClick={()=>newTrade()}>新建交易</button><button className="button secondary" onClick={()=>navigate('positions')}>管理当前持仓</button></div></section>}
        {page==='overview'&&(demo||legacyView)&&<>
          {!demo&&<HomeWorkspace records={records} trades={legacyTrades} settings={settings} openDay={openDay} newTrade={()=>newTrade()} onAction={actOnTrade} manage={()=>navigate('positions')}/>}<div className="metrics-grid">
            <Metric title="扣费后净收益" value={dollars(stats.totalPnl,true)} sub={`${stats.trades} 笔完整平仓 · ${stats.partialEvents} 次部分平仓`} icon={<ArrowUpRight size={18}/>} color={tone(stats.totalPnl)} data={periods.map(p=>p.cumulative)}/>
            <Metric title="已知风险 R 合计" value={stats.totalR===null?'—':number(stats.totalR,2)+' R'} sub={`R 覆盖 ${stats.knownR} / ${stats.trades} 笔 · 平均 ${number(stats.expectancy,2)} R`} icon={<Target size={18}/>} color={stats.totalR!==null?tone(stats.totalR):''} data={periods.flatMap(p=>p.totalR===null?[]:[p.totalR])}/>
            <Metric title="平均纪律评分" value={number(stats.score,0)} suffix="/ 100" sub={`计划遵守率 ${number(stats.complianceRate,0)}% · 参考线 ${activeSettings.targetDiscipline} 分`} icon={<ShieldCheck size={18}/>} color="gold" data={periods.flatMap(p=>p.score===null?[]:[p.score])}/>
            <Metric title="已平仓账户最大回撤" value={dollars(stats.maxDrawdown)} sub={`峰值回撤 ${number(stats.maxDrawdownPct,2)}% · 不含持仓浮亏`} icon={<ArrowDownLeft size={18}/>} color="negative" data={periods.map(p=>-p.drawdown)}/>
          </div>
          <details className="overview-research card" open={stats.trades>=5||demo}><summary>收益、纪律与回撤路径 {stats.trades<5&&!demo&&'· 样本积累中'}</summary><div className="charts-grid"><section className="card equity-card"><CardTitle title="收益的路径" subtitle={'完整验证期累计已平仓净收益 · '+(activeSettings.accountCurrency??'USD')} right={<span className="chart-legend"><i className="gold-bg"/>累计净收益</span>}/><ProfitChart periods={periods}/><div className="chart-foot"><span>期初账户 {dollars(activeSettings.capital)}</span><span>周期柱状收益见下方汇总</span></div></section><section className="card discipline-card"><CardTitle title="纪律与违规" subtitle="周期平均评分，与同期违规次数" right={<span className="badge subtle">先看执行</span>}/><DisciplineChart periods={periods} target={activeSettings.targetDiscipline}/><div className="chart-foot"><span><i className="green-bg"/>纪律评分</span><span><i className="pink-bg"/>违规次数</span></div></section></div>
          <div className="charts-grid lower"><section className="card"><CardTitle title="回撤观察" subtitle={'相对验证期账户历史峰值 · '+(activeSettings.accountCurrency??'USD')}/><DrawdownChart periods={periods}/><div className="chart-foot"><span>已平仓账户回撤</span><span>填报日内最大回撤 {stats.maxReportedDD===null?'未录入':dollars(stats.maxReportedDD)}</span></div></section><section className="card behavior-card"><CardTitle title="情绪与行动" subtitle="感到焦虑，与实际违规分别记录"/><div className="behavior-grid"><div><span>平均 FOMO</span><strong>{number(stats.fomo)}<small>/ 10</small></strong><div className="fomo-track"><div style={{width:(stats.fomo??0)*10+'%'}}/></div></div><div><span>冲动交易</span><strong>{stats.impulses}<small>次</small></strong><p>非计划主动出手</p></div><div><span>违规次数</span><strong className="negative">{stats.violations}<small>次</small></strong><p>按你的复盘填报</p></div><div><span>成功克制</span><strong className="positive">{stats.resisted}<small>次</small></strong><p>想出手，但守住计划</p></div></div></section></div>
          </details><section className={'assessment '+assessment.tone}><div className="assessment-icon"><Sparkles size={21}/></div><div><div className="eyebrow">阶段观察 {demo&&'· 示例结论'}</div><strong>{assessment.title}</strong><p>{assessment.body}</p></div><button className="icon-text" onClick={()=>navigate('review')}>查看周期评估<ChevronRight size={16}/></button></section>
          <section className="card"><CardTitle title="周期结果一览" subtitle={`${granularity==='week'?'周一至周日':granularity==='month'?'自然月':'每日'}汇总 · 当前筛选 ${stats.days} 天`}/><PeriodTable periods={periods}/></section>
        </>}
        {(page==='records'||page==='history')&&<>
          <section className="card historical-manager"><div><h2>历史记录管理</h2><p>选择任意日期，打开已保存的市场与状态；未记录日期可补录。</p></div><label className="date-filter"><span>日期</span><input type="date" aria-label="历史记录日期" value={historyDate} onChange={e=>setHistoryDate(e.target.value)}/></label><button className="button secondary" disabled={!historyDate} onClick={()=>openDay(historyDate)}>打开 / 编辑每日记录</button><button className="button secondary" disabled={demo||!historyDate} onClick={()=>newTrade(historyDate)}><Plus size={14}/>补录交易</button></section>
          {!demo&&records.some(d=>d.newTrades>0||d.openPositions>0)&&<p className="legacy-notice">旧日报自报的开仓及持仓数量仍保留。独立明细未补录的部分不会推断，也不与新交易数量相加。</p>}
          <section className="card records-card"><CardTitle title="每日复盘记录" subtitle={`当前筛选 ${list.length} 天 · 点击日期编辑`} right={<input className="search-input" aria-label="搜索记录" placeholder="搜索日期、模型或复盘…" value={query} onChange={e=>setQuery(e.target.value)}/>}/>
          {list.length?<div className="table-wrap"><table><thead><tr><th>交易日</th><th>市场 / 模型</th><th>净收益</th><th>已知 R</th><th>纪律</th><th>违规 / 冲动</th><th>FOMO</th><th>操作</th></tr></thead><tbody>{list.map(d=><tr key={d.date}><td><button className="date-link" onClick={()=>openDay(d.date)}>{d.date}</button><span className="cell-sub">{d.trades.filter(t=>!t.partial).length} 笔完整平仓 · {d.newTrades} 笔新开</span></td><td>{d.hasDailyState===false?'每日状态未记录':d.environment}<span className="cell-sub">{Array.from(new Set(d.trades.map(t=>t.model))).join(' · ')||'空仓观察'}</span></td><td className={'numeric '+tone(pnl(d))}>{dollars(pnl(d),true)}</td><td className="numeric">{number(recordR(d),2)}</td><td>{d.hasDailyState===false||d.disciplineAssessed===false?'未评价':<><span className={'score-pill '+(discipline(d,activeSettings.riskLimit)>=activeSettings.targetDiscipline?'good':'bad')}>{discipline(d,activeSettings.riskLimit)}</span><span className="cell-sub">{d.planCompliant?'遵守计划':'未守计划'}</span></>}</td><td className="numeric">{d.hasDailyState===false?'—':`${d.violations} / ${d.impulses}`}</td><td className="numeric">{d.hasDailyState===false||d.fomoRecorded===false?'—':d.fomo}<span className="dim"> /10</span></td><td><button className="icon-button" aria-label={'删除 '+d.date} onClick={()=>setDeleting(d.date)}><Trash2 size={16}/></button></td></tr>)}</tbody></table></div>:<Empty message={fullPoints.length?'此筛选下没有记录':'你的验证，从第一天开始'} action={makeNew}/>}
          </section>
          <section className="card"><CardTitle title="周期汇总" subtitle="切换上方的日、周、月，观察不同时间尺度"/><PeriodTable periods={periods}/></section>
          {priorRecords.length>0&&<section className="card"><CardTitle title="验证期外参考" subtitle="保留作复盘参考，不计入正式验证收益"/><div className="reference-list">{priorRecords.sort((a,b)=>a.date.localeCompare(b.date)).map(d=><div key={d.date} style={{display:'flex',alignItems:'center',gap:8}}><button style={{flex:1,minWidth:0}} onClick={()=>openDay(d.date)}><span>{d.date}</span><span>{dollars(pnl(d),true)}</span><span>编辑<ChevronRight size={14}/></span></button>{(demo||records.some(r=>r.date===d.date))&&<button type="button" className="icon-button" style={{width:'auto',flexShrink:0,padding:8,borderBottom:0}} aria-label={'删除期外观察 '+d.date} onClick={()=>setDeleting(d.date)}><Trash2 size={14}/></button>}</div>)}</div></section>}
          <div className="backup-row"><div><strong>保留一份完整记录</strong><span>JSON 包含逐笔交易与设置，CSV 便于查看每日统计。</span></div><button className="button secondary" onClick={()=>void exportAll()}><Download size={16}/>下载完整备份</button></div>
        </>}
        {['g1','opportunities','advanced'].includes(page)&&!demo&&<G1Workspace key={page+instrument+accountId} lockedTab={page==='opportunities'?'opportunities':page==='advanced'?'advanced':'stats'} trades={scopedTrades} records={legacyView?records:[]} settings={{...settings,_partialAccountScope:instrument!=='all'&&trades.some(t=>instrumentOf(t)!==instrument&&scopedTrades.some(u=>accountOf(u,settings)===accountOf(t,settings)))}} opportunities={opportunities.filter(o=>instrument==='all'||(!o.tradeId&&instrument==='XAU')||scopedTrades.some(t=>t.id===o.tradeId))} disabled={loading||!!error} newTrade={()=>{const selected=instrument==='all'?undefined:instrument,cfg=selected?instrumentConfig(settings,selected):null;const t={...blankTrade(),instrument:selected,...(cfg?{symbol:cfg.symbol,accountId:cfg.accountId,quoteSource:cfg.quoteSource,contract:structuredClone(cfg.contract)}:{}),framework:'G1' as const,model:'S1' as const,strategy:'G1-S' as const,direction:'short' as const,g1:{...blankG1(settings.g1),side:'short' as const}};setPendingOpportunity(null);setTradeEditor(t);}} openTrade={setTradeEditor} onOpportunitySaved={o=>setOpportunities(old=>[...old.filter(v=>v.id!==o.id),o])} fromOpportunity={o=>{const t={...blankTrade(o.date),instrument:undefined,framework:'G1' as const,model:(o.plan.side==='long'?'L1':'S1') as TradeRecord['model'],strategy:(o.plan.side==='long'?'G1-L':'G1-S') as TradeRecord['strategy'],direction:o.plan.side??'short',g1:structuredClone(o.plan)};setPendingOpportunity({opportunity:o,tradeId:t.id});setTradeEditor(t);}} openSettings={()=>navigate('rules')}/>}
        {(page==='review'||page==='models')&&(demo||legacyView)&&<>
          <div hidden={page!=='review'}><section className={'assessment '+assessment.tone}><div className="assessment-icon"><Target size={22}/></div><div><div className="eyebrow">当前筛选的阶段评估 {demo&&'· 示例'}</div><strong>{assessment.title}</strong><p>{assessment.body}</p></div></section>
          <div className="review-grid"><section className="card"><CardTitle title="策略有没有正期望？" subtitle="仅计划内、初始风险明确的已平仓单"/><div className="review-value">{number(assessment.plannedExpectancy,2)}<span>R / 笔</span></div><div className="review-detail"><span>可评估样本</span><strong>{assessment.plannedCount} / {activeSettings.minTrades} 笔</strong></div><p className="muted-note">最小样本数是可调整的参考门槛，不能证明统计显著性或未来盈利。</p><div className="review-detail"><span>全部平仓胜率</span><strong>{number(stats.winRate)}%</strong></div><div className="review-detail"><span>全部平仓利润因子</span><strong>{number(stats.profitFactor,2)}</strong></div></section><section className="card"><CardTitle title="执行有没有变稳定？" subtitle="不因一次赚亏改变纪律判断"/><div className="review-value">{number(stats.score,0)}<span>/ 100 分</span></div><div className="review-detail"><span>纪律参考线</span><strong>{activeSettings.targetDiscipline} 分</strong></div><div className="review-detail"><span>计划内净损益</span><strong className={tone(stats.inPlanPnl)}>{dollars(stats.inPlanPnl,true)}</strong></div><div className="review-detail"><span>计划外净损益</span><strong className={tone(stats.offPlanPnl)}>{dollars(stats.offPlanPnl,true)}</strong></div><p className="muted-note">计划外交易的盈利也单独列出，避免偶然赚钱掩盖执行偏差。</p></section></div>
          </div><details className="card model-comparison" open={page==='models'}><summary>四模型与其他模型表现 · 每笔交易只计一次</summary><section className="card"><CardTitle title="模型表现对照" subtitle="逐笔按模型拆分 · 初始风险缺失的交易不计入 R"/><div className="table-wrap"><table><thead><tr><th>模型</th><th>已平仓</th><th>净收益</th><th>平均 R</th><th>R覆盖</th><th>计划内</th><th>胜率</th></tr></thead><tbody>{MODELS.map(model=>{const days=filtered.map(d=>({...d,trades:d.trades.filter(t=>t.model===model)}));const s=summarize(days,activeSettings);return <tr key={model}><td><strong>{model}</strong><span className="cell-sub">{modelDescriptions.find(m=>m.id===model)?.name??'非标准模型'}</span></td><td>{s.trades} 笔</td><td className={'numeric '+tone(s.totalPnl)}>{dollars(s.totalPnl,true)}</td><td className="numeric">{number(s.expectancy,2)}</td><td>{s.knownR} / {s.trades}</td><td>{s.inPlanTrades} 笔</td><td>{number(s.winRate)}%</td></tr>;})}</tbody></table></div></section>
          </details><div hidden={page!=='review'}><section className="card"><CardTitle title="周期净收益" subtitle={'柱状图按当前日 / 周 / 月汇总 · '+(activeSettings.accountCurrency??'USD')}/><NetChart periods={periods}/><PeriodTable periods={periods}/></section>
                    <div className="review-guidance"><CheckCircle2 size={20}/><p>每次复盘先核对模型和纪律，再看收益。完成整个验证期后，把计划内平均 R、回撤、月度一致性和执行情况放在一起判断。</p></div></div>
        </>}
        {page==='models'&&legacyView&&<StrategyResearch trades={legacyTrades} settings={activeSettings}/>}
        {page==='rules'&&<>
          <details className="card advanced-research"><summary>保留的策略模型与纪律评分规则</summary><div className="system-callout"><ShieldCheck size={23}/><div><strong>波段结构判断 + 日内寻找入场点</strong><p>持仓数小时至数天。没有清晰趋势、处于宽幅混乱震荡时，保留空仓选项。</p></div></div>
          <div className="model-grid">{modelDescriptions.map(m=><section className="card model-card" key={m.id}><span className={'model-code '+(m.direction==='做空'?'short':'long')}>{m.id}</span><span className="model-direction">{m.direction}</span><h3>{m.name}</h3><p>{m.desc}</p></section>)}</div>
          <div className="rules-grid"><section className="card"><CardTitle title="风险与记录边界" subtitle="保持整个验证期的统计口径一致"/><ul className="rules-list"><li><Check size={16}/>账户基准 {dollars(activeSettings.capital)}，常规单笔风险 ${activeSettings.g1?.normalRiskMin??160}–${activeSettings.g1?.normalRiskMax??240}，绝对上限 ${activeSettings.riskLimit}。</li><li><Check size={16}/>仓位按止损距离和风险预算倒推，不能用“半仓”替代风险计算。</li><li><Check size={16}/>只录入已平仓、扣费后净损益；未平仓数量单独记录。</li><li><Check size={16}/>R = 该交易净损益 ÷ 明确的初始风险；缺失风险不补算。</li><li><Check size={16}/>验证期 {activeSettings.start} 至 {activeSettings.end}；期外日期保留作参考。</li></ul><div className="soft-note">晚间管理建议：北京时间19:30后原则上只管理已有仓位。是否违规仍由你按已确认计划复盘填报。</div></section><section className="card"><CardTitle title="纪律评分怎么算？" subtitle="透明的记录工具，分数不参与盈利计算"/><div className="score-rule"><span>遵守交易计划</span><strong>40 分</strong></div><div className="score-rule"><span>单笔风险合规</span><strong>25 分</strong></div><div className="score-rule"><span>无违规</span><strong>20 分</strong></div><div className="score-rule"><span>无冲动交易</span><strong>15 分</strong></div><p className="muted-note">每次违规从“无违规”项扣 5 分；每次冲动交易从“无冲动”项扣 5 分，各项最低 0 分。超单笔风险上限时，风险项为 0 分。FOMO 不直接扣分，守住计划的空仓日可得 100 分。</p></section></div>
          </details>{['multi','contract','fees'].includes(settingsTab)?<MultiAssetSettingsForm settings={activeSettings} save={saveConfig} disabled={loading||!!error}/>:<SettingsForm section={settingsTab} settings={activeSettings} demo={demo} disabled={!demo&&(loading||!!error)} save={saveConfig}/>}
        </>}
        {(page==='trades'||page==='positions')&&<TradeList key={page} trades={scopedTrades} settings={settings} positionsOnly={page==='positions'} onAction={actOnTrade} onChanged={t=>setTrades(old=>[...old.filter(v=>v.id!==t.id),t])} images={images} newTrade={newTrade} openTrade={t=>{setTradeAction(undefined);setTradeEditor(t);}} openDay={openDay}/>}
        {page==='psychology'&&legacyView&&<><section className="card"><CardTitle title="纪律与违规变化" subtitle="按实际打卡日评价，不因盈利自动判定守规"/><DisciplineChart periods={aggregate(fullPoints,settings,'week')} target={settings.targetDiscipline}/></section><PsychologyResearch trades={legacyTrades} settings={settings} openTrade={t=>{setTradeAction(undefined);setTradeEditor(t);}}/></>}
        {page==='sunday'&&(legacyView||unified)&&<><AccountPeriodReview records={financialRecords} trades={accountTrades} opportunities={opportunities} settings={settings} saveSettings={saveConfig}/><details className="card advanced-research"><summary>原有周日复盘 · 情绪、疲劳与专项详情</summary><SundayReview records={financialRecords} settings={settings} trades={accountTrades} images={images} opportunities={opportunities} rawRecords={records}/></details></>}
        {page==='growth'&&<><p className="muted-note">个人状态按日统一记录；统一账户的交易结果与情绪、睡眠和精力对照，不重复归入各品种。</p><PersonalGrowth showReview={false} records={financialRecords} settings={settings} trades={trades} images={images} opportunities={opportunities} rawRecords={records} exportAll={()=>void exportAll()}/></>}
        {!demo&&['overview','review','models','psychology','sunday','advanced','g1'].includes(page)&&<MultiAssetWorkspace trades={trades} records={records} settings={settings} instrument={instrument} accountId={accountId} start={filters.start} end={filters.end} openTrade={t=>{setTradeAction(undefined);setTradeEditor(t);}}/>}

        <footer><span>黄金策略实验室 · 三个月，让执行留下证据</span><span><LockKeyhole size={12}/>私人访问 · {String(settings.accountCurrency??'USD')} · 北京时间</span></footer>
      </main>
    </div>
    {editor&&<DayEditor key={editor.date} initial={editor} records={rawRecords} settings={activeSettings} demo={demo} saving={saving} onClose={()=>{setEditor(null);if(!demo)void load();}} save={saveDay} trades={trades} onNewTrade={newTrade} onOpenTrade={t=>setTradeEditor(t)}/>}
    {tradeEditor&&!demo&&<TradeDialog initialAction={tradeAction} key={tradeEditor.id} initial={tradeEditor} settings={settings} day={records.find(d=>d.date===tradeEditor.openedDate)} onClose={()=>{setTradeEditor(null);setTradeAction(undefined);}} onOpenDay={openDay} onSaved={t=>{setTrades(old=>[...old.filter(v=>v.id!==t.id),t]);if(pendingOpportunity?.tradeId===t.id&&hasExecution(t)){void api<{opportunity:Opportunity}>('/api/opportunities','PUT',{...pendingOpportunity.opportunity,tradeId:t.id}).then(d=>{setOpportunities(old=>[...old.filter(o=>o.id!==d.opportunity.id),d.opportunity]);setPendingOpportunity(null);}).catch(e=>setToast('交易已保存；机会关联未保存：'+e.message+'。请在机会观察中手动关联。'));}}} onImagesChanged={(next,id)=>setImages(old=>[...old.filter(i=>i.tradeId!==id),...next])}/>}
    {showInfo&&<Modal title="统一统计口径" onClose={()=>setShowInfo(false)}><div className="info-content"><p><strong>收益：</strong>仅验证期内、已平仓的逐笔扣费后净损益。每次实际平仓按平仓日期计入净收益；未平仓浮盈亏不计入。完整平仓笔数与部分平仓事件分开显示。</p><p><strong>R：</strong>整笔已实现净损益 / 明确的正数初始风险，在全部平仓后计算一次。合计只包含风险明确的交易，同时显示覆盖率。日 R 合计不等于日收益除以统一风险。</p><p><strong>回撤：</strong>以账户基准 + 累计已平仓净收益计算历史峰值回撤，包含起始账户高水位。不包含浮动损益、出入金及日内路径。筛选后仍沿用完整验证期的历史峰值。</p><p><strong>填报日内回撤：</strong>独立展示你输入的日内最大回撤，不与账户回撤相加。周期汇总取最大值。</p><p><strong>聚合：</strong>日 / 周 / 月净收益、R和次数求和；纪律、FOMO按实际打卡日取平均；周一至周日为一周，月为自然月。未打卡日不视作零收益或守规。</p><p><strong>筛选：</strong>日期、守规和模型筛选影响全部统计与图表。模型筛选选出含该模型的日子，单模型表现另按逐笔计算。</p><p><strong>结论：</strong>评分与样本门槛用于阶段观察，没有月度盈利任务，也不会根据少量盈利就判定系统长期有效。</p></div></Modal>}
    {deleting&&<Modal title="删除这一天的记录？" onClose={()=>!saving&&setDeleting(null)}><p className="modal-description">将删除 {deleting} 的{demo?'示例':'正式'}每日市场与状态。独立交易、旧汇总交易和截图保留；删除的每日内容写入备份及修改历史。</p><div className="modal-actions"><button className="button secondary" disabled={saving} onClick={()=>setDeleting(null)}>保留记录</button><button className="button danger" disabled={saving} onClick={()=>void removeDay(deleting)}>{saving?'删除中…':'确认删除'}</button></div></Modal>}
    {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/>{toast}</div>}
  </div>;
}

function Metric({title,value,sub,icon,color,suffix,data}:{title:string;value:string;sub:string;icon:React.ReactNode;color?:string;suffix?:string;data:number[]}) {const low=Math.min(...data),high=Math.max(...data);const points=data.map((v,i)=>`${data.length>1?i/(data.length-1)*104:52},${high>low?30-(v-low)/(high-low)*28:15}`).join(' ');return <section className="metric"><div className="metric-top"><span>{title}</span><span className="metric-icon">{icon}</span></div><div className={'metric-value '+color}>{value}<small>{suffix}</small></div><div className="metric-sub">{sub}</div>{data.length>1&&<svg className={'sparkline '+color} viewBox="0 0 110 35" aria-hidden="true"><polyline points={points} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>}</section>;}
function CardTitle({title,subtitle,right}:{title:string;subtitle?:string;right?:React.ReactNode}){return <div className="card-title"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{right}</div>;}
function Empty({message='此筛选下没有记录',action}:{message?:string;action?:()=>void}){return <div className="empty"><div className="empty-icon"><ClipboardList size={27}/></div><strong>{message}</strong><p>没有交易也可以记录你的观察、纪律与情绪。</p>{action&&<button className="button secondary" onClick={action}><Plus size={15}/>写下第一条记录</button>}</div>;}
const tooltipStyle={border:'1px solid #e5e7e4',borderRadius:10,boxShadow:'0 8px 24px #19352b12',fontSize:12};
const axis={axisLine:false,tickLine:false,tick:{fontSize:11,fill:'#8a9390'},minTickGap:25};
function ProfitChart({periods}:{periods:ReturnType<typeof aggregate>}){if(!periods.length)return <Empty/>;return <div className="chart-container"><ResponsiveContainer width="100%" height="100%"><AreaChart data={periods} margin={{top:18,right:12,bottom:0,left:0}}><defs><linearGradient id="profitGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#ad8b42" stopOpacity={0.2}/><stop offset="1" stopColor="#ad8b42" stopOpacity={0.01}/></linearGradient></defs><CartesianGrid strokeDasharray="4 5" vertical={false} stroke="#edf0ec"/><XAxis dataKey="label" {...axis}/><YAxis {...axis} width={54} tickFormatter={v=>'$'+(Math.abs(v)>=1000?(v/1000).toFixed(1)+'k':v)}/><Tooltip contentStyle={tooltipStyle} formatter={v=>[dollars(Number(v),true),'累计净收益']}/><ReferenceLine y={0} stroke="#d8dfd8"/><Area type="linear" dataKey="cumulative" stroke="#ad8b42" strokeWidth={2.4} fill="url(#profitGradient)" activeDot={{r:5,stroke:'white',strokeWidth:2}}/></AreaChart></ResponsiveContainer></div>;}
function DisciplineChart({periods,target}:{periods:ReturnType<typeof aggregate>;target:number}){if(!periods.length)return <Empty/>;return <div className="chart-container"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={periods} margin={{top:18,right:0,bottom:0,left:-20}}><CartesianGrid vertical={false} strokeDasharray="4 5" stroke="#edf0ec"/><XAxis dataKey="label" {...axis}/><YAxis yAxisId="score" {...axis} domain={[0,100]}/><YAxis yAxisId="violation" orientation="right" {...axis} allowDecimals={false} width={30}/><Tooltip contentStyle={tooltipStyle} formatter={(v,name)=>[number(Number(v)),name==='score'?'平均纪律评分':'违规次数']}/><ReferenceLine yAxisId="score" y={target} stroke="#a7c3b0" strokeDasharray="4 4"/><Bar yAxisId="violation" dataKey="violations" fill="#e7b5ac" radius={[3,3,0,0]} maxBarSize={14}/><Line yAxisId="score" dataKey="score" type="linear" stroke="#4c8c72" strokeWidth={2.4} dot={false} activeDot={{r:4}}/></ComposedChart></ResponsiveContainer></div>;}
function DrawdownChart({periods}:{periods:ReturnType<typeof aggregate>}){if(!periods.length)return <Empty/>;const data=periods.map(p=>({...p,dd:-p.drawdown}));return <div className="chart-container short-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data} margin={{top:15,right:12,bottom:0,left:0}}><CartesianGrid vertical={false} strokeDasharray="4 5" stroke="#edf0ec"/><XAxis dataKey="label" {...axis}/><YAxis {...axis} width={54} tickFormatter={v=>'$'+Math.abs(v)}/><Tooltip contentStyle={tooltipStyle} formatter={v=>[dollars(Math.abs(Number(v))),'账户峰值回撤']}/><Area type="linear" dataKey="dd" stroke="#c17e74" strokeWidth={2} fill="#f5e7e3"/></AreaChart></ResponsiveContainer></div>;}
function NetChart({periods}:{periods:ReturnType<typeof aggregate>}){if(!periods.length)return <Empty/>;return <div className="chart-container"><ResponsiveContainer width="100%" height="100%"><BarChart data={periods}><CartesianGrid vertical={false} strokeDasharray="4 5" stroke="#edf0ec"/><XAxis dataKey="label" {...axis}/><YAxis {...axis} tickFormatter={v=>'$'+v}/><Tooltip contentStyle={tooltipStyle} formatter={v=>[dollars(Number(v),true),'周期净收益']}/><ReferenceLine y={0} stroke="#cbd4cb"/><Bar dataKey="totalPnl" fill="#86a895" radius={[4,4,0,0]} maxBarSize={35}/></BarChart></ResponsiveContainer></div>;}
function PeriodTable({periods}:{periods:ReturnType<typeof aggregate>}){return periods.length?<div className="table-wrap"><table><thead><tr><th>周期</th><th>日记录 / 完整平仓</th><th>净收益</th><th>已知 R 合计</th><th>平均纪律</th><th>最大账户回撤</th><th>违规 / 冲动</th><th>平均 FOMO</th></tr></thead><tbody>{periods.slice().reverse().map(p=><tr key={p.key}><td><strong>{p.label}</strong></td><td>{p.days} 天 / {p.trades} 笔<span className="cell-sub">新开 {p.newTrades} · 部分平仓 {p.partialEvents} 次</span></td><td className={'numeric '+tone(p.totalPnl)}>{dollars(p.totalPnl,true)}</td><td className="numeric">{number(p.totalR,2)}<span className="cell-sub">覆盖 {p.knownR}/{p.trades}</span></td><td>{number(p.score,0)}<span className="dim"> /100</span></td><td className="numeric">{dollars(p.maxDrawdown)}</td><td>{p.violations} / {p.impulses}</td><td>{number(p.fomo)}<span className="dim"> /10</span></td></tr>)}</tbody></table></div>:<Empty/>;}

function Modal({title,children,onClose,wide=false}:{title:string;children:React.ReactNode;onClose:()=>void;wide?:boolean}){
  const ref=useDialogFocus(onClose);
  return <div className="modal-overlay"><div className={'modal '+(wide?'wide':'')} ref={ref} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1}><div className="modal-header"><h2>{title}</h2><button className="icon-button" aria-label="关闭" onClick={onClose}><X size={20}/></button></div>{children}</div></div>;
}
function Choice({label,value,onChange,labels=['是','否']}:{label:string;value:boolean;onChange:(v:boolean)=>void;labels?:[string,string]}){return <div className="form-field"><span className="field-label">{label}</span><div className="choice">{[true,false].map((v,i)=><button type="button" key={String(v)} aria-pressed={value===v} className={value===v?'selected':''} onClick={()=>onChange(v)}>{labels[i]}</button>)}</div></div>;}
function NumberField({label,value,onChange,min=0,max=10000,optional=false,step=1}:{label:string;value:number|null;onChange:(v:number|null)=>void;min?:number;max?:number;optional?:boolean;step?:number}){return <label className="form-field"><span className="field-label">{label}</span><input type="number" value={value??''} min={min} max={max} step={step} required={!optional} placeholder={optional?'可留空':''} onChange={e=>onChange(e.target.value===''?optional?null:0:Number(e.target.value))}/></label>;}

function SettingsForm({settings,demo,disabled,save,section='account'}:{settings:Settings;demo:boolean;disabled:boolean;save:(s:Settings)=>Promise<void>;section?:string}){
  const [value,setValue]=useState(settings),[saving,setSaving]=useState(false),[error,setError]=useState('');
  const ref=useRef(value);const update=(v:Settings)=>{ref.current=v;setValue(v);};
  useEffect(()=>{ref.current=settings;setValue(settings);},[settings]);
  const config=value.g1??DEFAULT_G1;
  const updateG1=(patch:Partial<typeof config>)=>update({...ref.current,g1:{...(ref.current.g1??DEFAULT_G1),...patch}});
  async function submit(e:React.FormEvent){e.preventDefault();setError('');const parsed=settingsSchema.safeParse(ref.current);if(!parsed.success){setError(parsed.error.issues[0].message);return;}setSaving(true);try{await save(parsed.data as Settings);}catch(e){setError((e as Error).message);}finally{setSaving(false);}}
  return <section className="card settings-card"><CardTitle title={settingTabs.find(([key])=>key===section)?.[1]??'账户与风险'} subtitle={demo?'调整仅作用于隔离示例':'保存后仅成为新增计划的默认参数；历史计划快照保留'}/><form onSubmit={submit}><fieldset className="editor-fieldset" disabled={disabled||saving}><div className="settings-content">
  {section==='account'&&<><div className="form-grid"><NumberField label="统一账户初始资金基准 · USD" value={(unifiedAccountConfig(value)??DEFAULT_UNIFIED_ACCOUNT).capital} min={0.01} max={1e9} step={0.01} onChange={v=>{const current=ref.current;update({...current,capital:v??0,accountCurrency:'USD',multiAsset:{...current.multiAsset,baseCurrency:'USD',unifiedAccount:{...structuredClone(unifiedAccountConfig(current)??DEFAULT_UNIFIED_ACCOUNT),capital:v??0}}});}}/><div className="form-field"><span className="field-label">账户范围</span><strong>原黄金账户 · USD</strong><small>黄金、纳指、BTC共用一份资金与风险预算。</small></div></div><p className="muted-note">初始资金是验证期的计算基准，不会将当前余额重置为此金额。各品种合约与费用在“多品种配置”中统一维护。</p></>}
  {section==='fees'&&<div className="form-grid"><NumberField optional label="预计开仓费 / 每数量单位" value={config.contract.entryFeePerQty} step={.0001} onChange={v=>updateG1({contract:{...config.contract,entryFeePerQty:v}})}/><NumberField optional label="预计平仓费 / 每数量单位" value={config.contract.exitFeePerQty} step={.0001} onChange={v=>updateG1({contract:{...config.contract,exitFeePerQty:v}})}/><NumberField optional label="预计止损滑点 · 价格点数" value={config.contract.slippagePrice} step={.0001} onChange={v=>updateG1({contract:{...config.contract,slippagePrice:v}})}/><p className="muted-note full">预计费用用于计划风险。实际成交费用在每次开平仓中核对，估算费用会独立标记。成交价格已包含的滑点不再次扣除。</p></div>}
  {section==='account'&&<><RiskRuleSettings settings={value} onChange={update}/><details className="form-section"><summary>旧记录兼容参数</summary><p className="muted-note">用于旧版每日评分和缺少规则快照的记录；新交易采用上方双层预算。</p><NumberField label="旧版硬风险阈值" value={value.riskLimit} min={0.01} max={1e7} step={0.01} onChange={v=>update({...ref.current,riskLimit:v??0})}/></details></>}
  {section==='contract'&&<ContractFields value={config.contract} onChange={contract=>updateG1({contract})}/>}
  {['g1','advanced'].includes(section)&&<G1SettingsFields value={value.g1} onChange={g1=>update({...ref.current,g1})} onRuleDraft={v=>{ref.current={...ref.current,g1:{...(ref.current.g1??DEFAULT_G1),confirmationRule:v}};}} onCommit={()=>setValue({...ref.current})}/>}
  {section==='discipline'&&<div className="form-grid"><NumberField label="纪律评分参考线" value={value.targetDiscipline} max={100} onChange={v=>update({...ref.current,targetDiscipline:v??0})}/><NumberField label="有效样本参考数" value={value.minTrades} min={1} onChange={v=>update({...ref.current,minTrades:v??0})}/><p className="muted-note full">原有评分：计划40、风险25、违规20、冲动15。尚未评价的日子不默认100分，不参与纪律均值。少量盈利不能验证稳定优势。</p></div>}
  {section==='period'&&<div className="form-grid"><label className="form-field"><span className="field-label">验证开始</span><input type="date" required value={value.start} onChange={e=>update({...ref.current,start:e.target.value})}/></label><label className="form-field"><span className="field-label">验证结束</span><input type="date" required value={value.end} onChange={e=>update({...ref.current,end:e.target.value})}/></label><p className="muted-note full">期外记录继续保留。修改验证窗口改变当前统计区间，不删除原始记录。</p></div>}
  {section==='data'&&<p className="muted-note">完整备份可从记录页底部或个人成长页导出；交易详情可下载原始截图。所有正式数据归当前账号所有，示例和草稿不计入正式统计。</p>}
  </div><div className="settings-footer"><p>当前规则版本 {config.ruleVersion??'旧版'} {config.effectiveAt?'· '+new Date(config.effectiveAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'· 首次更新时记录生效时间'}</p><button type="submit" className="button primary" disabled={saving}>{saving?'保存中…':'保存设置'}</button></div>{error&&<div className="error-banner" role="alert">{error}</div>}</fieldset></form></section>;
}
